const tickets = $input.all();
const now = new Date();

const overdueTickets = tickets.filter(item => {
  const ticket = item.json;

  const status = String(ticket.status || '')
    .trim()
    .toLowerCase();

  // Ignore completed tickets
  if (['resolved', 'closed'].includes(status)) {
    return false;
  }

  // Only include Open or In Progress tickets
  if (!['open', 'in progress'].includes(status)) {
    return false;
  }

  // Require a ticket ID and follow-up date
  if (!ticket.ticket_id || !ticket.follow_up_due_at) {
    return false;
  }

  const dueDate = new Date(ticket.follow_up_due_at);

  if (Number.isNaN(dueDate.getTime())) {
    return false;
  }

  // Check whether the deadline has passed
  return dueDate < now;
});

return overdueTickets;

const tickets = $input.all().map(item => item.json);

// Show urgent tickets first
const rank = { Urgent: 0, High: 1, Normal: 2, Low: 3 };

tickets.sort((a, b) =>
  (rank[a.priority] ?? 4) - (rank[b.priority] ?? 4)
);

const reportDate = new Date().toLocaleDateString('en-ZA', {
  timeZone: 'Africa/Johannesburg',
  day: '2-digit',
  month: 'long',
  year: 'numeric'
});

const urgentCount = tickets.filter(
  t => t.priority === 'Urgent'
).length;

const highCount = tickets.filter(
  t => t.priority === 'High'
).length;

let report = `SMARTDESK - DAILY SUPPORT REPORT
Date: ${reportDate}

OVERDUE TICKETS: ${tickets.length}
Urgent: ${urgentCount}
High Priority: ${highCount}

----------------------------------------
`;

tickets.forEach((ticket, index) => {
  report += `
${index + 1}. ${ticket.ticket_id}
Subject: ${ticket.subject}
Customer: ${ticket.customer_email}
Priority: ${ticket.priority}
Status: ${ticket.status}
Due: ${ticket.follow_up_due_at}
Summary: ${ticket.summary || ticket.description}

----------------------------------------
`;
});

report += `
Please review and update the outstanding tickets.

Automated report generated by SmartDesk.
`;

return [{
  json: {
    report_date: reportDate,
    total_overdue: tickets.length,
    urgent_count: urgentCount,
    high_count: highCount,
    email_subject: `SmartDesk Daily Report - ${tickets.length} Overdue Tickets`,
    email_body: report
  }
}];
